package com.company.platform.inventory.infrastructure;
import java.util.*;import org.apache.kafka.clients.producer.ProducerConfig;import org.apache.kafka.common.serialization.StringSerializer;import org.springframework.context.annotation.*;import org.springframework.kafka.core.*;import org.springframework.kafka.support.serializer.JsonSerializer;import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;import org.springframework.kafka.support.serializer.JsonDeserializer;import org.springframework.kafka.listener.*;import org.springframework.util.backoff.FixedBackOff;
@Configuration public class KafkaConfiguration{@Bean ProducerFactory<String,Object> producerFactory(){Map<String,Object> p=new HashMap<>();p.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG,System.getenv().getOrDefault("KAFKA_BOOTSTRAP_SERVERS","localhost:9092"));p.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG,StringSerializer.class);p.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,JsonSerializer.class);return new DefaultKafkaProducerFactory<>(p);}@Bean KafkaTemplate<String,Object> kafkaTemplate(ProducerFactory<String,Object> f){return new KafkaTemplate<>(f);}@Bean ConsumerFactory<String,com.fasterxml.jackson.databind.JsonNode> inventoryConsumerFactory(){Map<String,Object> p=new HashMap<>();p.put(org.apache.kafka.clients.consumer.ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG,System.getenv().getOrDefault("KAFKA_BOOTSTRAP_SERVERS","localhost:9092"));p.put(org.apache.kafka.clients.consumer.ConsumerConfig.GROUP_ID_CONFIG,"inventory-service");p.put(org.apache.kafka.clients.consumer.ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG,org.apache.kafka.common.serialization.StringDeserializer.class);p.put(org.apache.kafka.clients.consumer.ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,JsonDeserializer.class);p.put(JsonDeserializer.TRUSTED_PACKAGES,"*");return new DefaultKafkaConsumerFactory<>(p,new org.apache.kafka.common.serialization.StringDeserializer(),new JsonDeserializer<>(com.fasterxml.jackson.databind.JsonNode.class,false));}@Bean ConcurrentKafkaListenerContainerFactory<String,com.fasterxml.jackson.databind.JsonNode> inventoryKafkaListenerContainerFactory(ConsumerFactory<String,com.fasterxml.jackson.databind.JsonNode> cf,KafkaTemplate<String,Object> template){var f=new ConcurrentKafkaListenerContainerFactory<String,com.fasterxml.jackson.databind.JsonNode>();f.setConsumerFactory(cf);f.setCommonErrorHandler(new DefaultErrorHandler(new DeadLetterPublishingRecoverer(template),new FixedBackOff(1000L,2L)));return f;}}
